WITH with_latest AS (SELECT s.*, latest.delivered_date FROM orders s LEFT JOIN LATERAL (SELECT c.delivered_date FROM shipments c WHERE c.order_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT DATE_TRUNC('YEAR', order_date) AS year_start, status, store_id, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count, ROUND(AVG(discount), 2) AS avg_discount, STDDEV_SAMP(amount) AS amount_stddev, COUNT(CASE WHEN channel = 'partner' THEN 1 END) AS partner_count_2 FROM with_latest GROUP BY DATE_TRUNC('YEAR', order_date), status, store_id ORDER BY partner_count_2 DESC NULLS LAST;
